const calculateEndDate = (startDateStr, months)=>{
    if (!startDateStr || months <= 0) return "";
    const d = new Date(startDateStr);
    if (isNaN(d.getTime())) return "";
    d.setMonth(d.getMonth() + months);
    return d.toISOString().split("T")[0];
};
const calculateMonthsBetween = (startStr, endStr)=>{
    if (!startStr || !endStr) return 0;
    const s = new Date(startStr);
    const e = new Date(endStr);
    if (isNaN(s.getTime()) || isNaN(e.getTime())) return 0;
    const diffYears = e.getFullYear() - s.getFullYear();
    const diffMonths = e.getMonth() - s.getMonth();
    return Math.max(1, diffYears * 12 + diffMonths);
};
